			// --------------------------------------------------------------------------------
			// Included in Statamic's base Text.vue
			// --------------------------------------------------------------------------------
			// The value attribute specifies the value of an <input> element.
			//
			// Valid for input types:
			//   - date:           Sets the initial date (e.g., `2025-07-25`; empty if unset).
			//   - datetime-local: Sets the initial date and time (e.g., `2025-07-25T09:36`;
			//                     empty if unset).
			//   - email:          Sets the initial email (e.g., `user@example.com`; empty if
			//                     unset).
			//   - month:          Sets the initial year and month (e.g., `2025-07`; empty if
			//                     unset).
			//   - number:         Sets the initial number (e.g., `42`; empty if unset).
			//   - password:       Sets the initial masked text (empty if unset).
			//   - search:         Sets the initial search text (empty if unset).
			//   - tel:            Sets the initial phone number (e.g., `+1-555-555-5555`;
			//                     empty if unset).
			//   - text:           Sets the initial text (empty if unset).
			//   - time:           Sets the initial time (e.g., `09:36`; empty if unset).
			//   - url:            Sets the initial URL (e.g., `https://example.com`; empty if
			//                     unset).
			//   - week:           Sets the initial year and week (e.g., `2025-W30`; empty if
			//                     unset).
			//
			// Syntax: <input value="text">
			//
			// Attribute Values:
			//   - [text]: Specifies the value of the <input> element
			// --------------------------------------------------------------------------------
			value: { required: true },

